import {useCallback, useEffect, useRef, useState} from 'react';
export function useCEPreviewerAnimations({
  currentProduct,
  nameImageUrls,
  numberImageUrls,
  currentCustomizationType,
  allCharImagesLoadedPromise,
  isLoadingCustomization,
}) {
  const [productImageAnimClass, setProductImageAnimClass] = useState('');
  const [lettersAnimationClass, setLettersAnimationClass] = useState('');
  const [numbersAnimationClass, setNumbersAnimationClass] = useState('');
  const [displayedProductImageUrl, setDisplayedProductImageUrl] = useState(
    currentProduct?.images?.[0]?.url || '',
  );
  const [displayedName, setDisplayedName] = useState([]);
  const [displayedNumber, setDisplayedNumber] = useState([]);
  const [isProductImageTransitioning, setIsProductImageTransitioning] =
    useState(false);
  const pendingProductImageUrlRef = useRef(null);
  const animationTimingsRef = useRef(null);
  // prev name and number counters
  const prevNameLengthRef = useRef(nameImageUrls.length);
  const prevNumberLengthRef = useRef(numberImageUrls.length);
  const prevCustomizationTypeRef = useRef(currentCustomizationType);
  const computeHideTime = (nameLength, numberLength) => {
    if (!animationTimingsRef.current) return 0;
    const {stepMs, durationMs} = animationTimingsRef.current;
    const nameTime = (nameLength - 1) * stepMs + durationMs;
    const numberTime = (numberLength - 1) * stepMs + durationMs;
    return nameTime + numberTime;
  };
  useEffect(() => {
    const style = getComputedStyle(document.documentElement);
    animationTimingsRef.current = {
      stepMs: parseFloat(style.getPropertyValue('--ce-char-step-ms')) || 0,
      durationMs:
        parseFloat(style.getPropertyValue('--ce-char-duration-ms')) || 0,
    };
  }, []);
  const completeFadeOutTransition = useCallback(() => {
    const nextImageUrl = pendingProductImageUrlRef.current;
    if (!nextImageUrl) return;
    setDisplayedProductImageUrl(nextImageUrl);
    pendingProductImageUrlRef.current = null;
  }, []);
  const completeFadeInTransition = useCallback(() => {
    setProductImageAnimClass('');
    setIsProductImageTransitioning(false);
  }, []);
  useEffect(() => {
    const nextImageUrl = currentProduct?.customizationImage?.image?.url;
    if (!nextImageUrl) return;
    if (!displayedProductImageUrl) {
      setDisplayedProductImageUrl(nextImageUrl);
      return;
    }
    if (nextImageUrl === displayedProductImageUrl) return;
    const hideTime = computeHideTime(
      nameImageUrls.length,
      numberImageUrls.length,
    );
    if (hideTime > 0) {
      setLettersAnimationClass('is-hiding');
      setNumbersAnimationClass('is-hiding');
      setIsProductImageTransitioning(true);
      setTimeout(() => {
        pendingProductImageUrlRef.current = nextImageUrl;
        setProductImageAnimClass('fade-out');
      }, hideTime);
    }
  }, [
    currentProduct,
    displayedProductImageUrl,
    nameImageUrls,
    numberImageUrls,
  ]);
  // name and number (player included) animation logic
  useEffect(() => {
    if (isLoadingCustomization || isProductImageTransitioning) return;
    let letterAnimationClass = '';
    let numberAnimationClass = '';
    let localHideTime = 0;
    if (currentCustomizationType === 'player') {
      setLettersAnimationClass('is-hiding');
      setNumbersAnimationClass('is-hiding');
      localHideTime = computeHideTime(
        nameImageUrls.length,
        numberImageUrls.length,
      );
      letterAnimationClass = numberAnimationClass = 'is-typing';
    } else {
      if (
        prevNameLengthRef.current === nameImageUrls.length &&
        prevNumberLengthRef.current === numberImageUrls.length
      ) {
        setLettersAnimationClass('is-hiding');
        setNumbersAnimationClass('is-hiding');
        localHideTime = computeHideTime(
          prevNameLengthRef.current,
          prevNumberLengthRef.current,
        );
        letterAnimationClass = numberAnimationClass = 'is-typing';
      } else if (nameImageUrls.length === 0 && numberImageUrls.length === 0) {
        setLettersAnimationClass('is-hiding');
        setNumbersAnimationClass('is-hiding');
        localHideTime = computeHideTime(
          prevNameLengthRef.current,
          prevNumberLengthRef.current,
        );
        letterAnimationClass = numberAnimationClass = 'is-typing-last';
      } else if (prevNameLengthRef.current > nameImageUrls.length) {
        setLettersAnimationClass('is-hiding-last');
        localHideTime = computeHideTime(1, 0);
        letterAnimationClass = numberAnimationClass = '';
      } else if (prevNumberLengthRef.current > numberImageUrls.length) {
        setNumbersAnimationClass('is-hiding-last');
        localHideTime = computeHideTime(0, 1);
        letterAnimationClass = numberAnimationClass = '';
      } else if (prevNameLengthRef.current < nameImageUrls.length) {
        letterAnimationClass = 'is-typing-last';
        numberAnimationClass = '';
      } else if (prevNumberLengthRef.current < numberImageUrls.length) {
        numberAnimationClass = 'is-typing-last';
        letterAnimationClass = '';
      }
    }
    const hideTimeout = setTimeout(() => {
      // if customization type changed, reset name and number because promise resolution might come after user interaction, causing wrong name/number to be displayed with wrong animation
      if (prevCustomizationTypeRef.current !== currentCustomizationType) {
        setDisplayedName([]);
        setDisplayedNumber([]);
      }
      prevCustomizationTypeRef.current = currentCustomizationType;
      allCharImagesLoadedPromise?.then(() => {
        prevNameLengthRef.current = nameImageUrls.length;
        prevNumberLengthRef.current = numberImageUrls.length;
        setDisplayedName(nameImageUrls);
        setDisplayedNumber(numberImageUrls);
        setLettersAnimationClass(letterAnimationClass);
        setNumbersAnimationClass(numberAnimationClass);
      });
    }, localHideTime);
    return () => clearTimeout(hideTimeout);
  }, [
    nameImageUrls,
    numberImageUrls,
    currentCustomizationType,
    allCharImagesLoadedPromise,
    isLoadingCustomization,
    isProductImageTransitioning,
  ]);
  return {
    completeFadeOutTransition,
    completeFadeInTransition,
    setProductImageAnimClass,
    productImageAnimClass,
    lettersAnimationClass,
    numbersAnimationClass,
    displayedProductImageUrl,
    displayedName,
    displayedNumber,
  };
}
